{"path": "parser.mjs", "content": "const SKU_PATTERN = /^[A-Z][A-Z0-9-]*$/;
const DIGITS_PATTERN = /^[0-9]+$/;

function parseSafeInteger(value, field, lineNumber) {
  if (!DIGITS_PATTERN.test(value)) {
    throw new Error(`Malformed row ${lineNumber}: invalid ${field}`);
  }
  const parsed = Number(value);
  if (!Number.isSafeInteger(parsed)) {
    throw new RangeError(`Row ${lineNumber}: ${field} exceeds Number.MAX_SAFE_INTEGER`);
  }
  return parsed;
}

export function parseOrders(text) {
  if (typeof text !== 'string') {
    throw new TypeError('parseOrders expects a string');
  }

  const orders = [];
  const lines = text.split('\n');

  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i].replace(/\r$/, '');
    if (line.trim() === '') {
      continue;
    }

    const fields = line.split(',');
    if (fields.length !== 3) {
      throw new Error(`Malformed row ${i + 1}: expected 3 fields`);
    }

    const sku = fields[0].trim();
    const quantityText = fields[1].trim();
    const unitPriceText = fields[2].trim();

    if (!SKU_PATTERN.test(sku)) {
      throw new Error(`Malformed row ${i + 1}: invalid SKU`);
    }

    const quantity = parseSafeInteger(quantityText, 'quantity', i + 1);
    if (quantity <= 0) {
      throw new Error(`Malformed row ${i + 1}: quantity must be positive`);
    }

    const unitPriceCents = parseSafeInteger(unitPriceText, 'unitPriceCents', i + 1);

    orders.push({ sku, quantity, unitPriceCents });
  }

  return orders;
}
"}

