{"path": "report.mjs", "content": "import { parseOrders } from './parser.mjs';

export function buildReport(text) {
  const rows = parseOrders(text);

  const bySku = new Map();
  let totalUnits = 0;
  let totalCents = 0;

  for (const row of rows) {
    totalUnits += row.quantity;
    if (!Number.isSafeInteger(totalUnits)) {
      throw new RangeError('totalUnits exceeds Number.MAX_SAFE_INTEGER');
    }

    const lineCents = row.quantity * row.unitPriceCents;
    if (!Number.isSafeInteger(lineCents)) {
      throw new RangeError('line total exceeds Number.MAX_SAFE_INTEGER');
    }

    totalCents += lineCents;
    if (!Number.isSafeInteger(totalCents)) {
      throw new RangeError('totalCents exceeds Number.MAX_SAFE_INTEGER');
    }

    const existing = bySku.get(row.sku);
    if (existing === undefined) {
      bySku.set(row.sku, { sku: row.sku, quantity: row.quantity, totalCents: lineCents });
    } else {
      existing.quantity += row.quantity;
      if (!Number.isSafeInteger(existing.quantity)) {
        throw new RangeError('aggregate quantity exceeds Number.MAX_SAFE_INTEGER');
      }
      existing.totalCents += lineCents;
      if (!Number.isSafeInteger(existing.totalCents)) {
        throw new RangeError('aggregate cents exceeds Number.MAX_SAFE_INTEGER');
      }
    }
  }

  const items = [...bySku.values()].sort((a, b) => (a.sku < b.sku ? -1 : a.sku > b.sku ? 1 : 0));

  return { items, totalUnits, totalCents };
}
"}

